/**
 * Scientific data layers from NASA Solar System Treks (Moon Trek). Generated by scratchpad/gen_catalog.py from a live
 * probe of each layer's WMTS capabilities and a real sample tile (every id below returned image data). The text is
 * written for SouthWatch; the pictures are NASA's own colourisation, which the catalog does not describe with units or
 * a legend, so SouthWatch shows none it cannot prove.
 */
export type LayerGroupId = "light" | "terrain" | "thermal" | "chemistry" | "water" | "gravity" | "geology" | "imagery";
export type LayerTag = "MEASURED" | "COMPUTED" | "MODELED";

export interface DataLayer {
  /** Moon Trek layer id (also the WMTS identifier). */
  id: string;
  group: LayerGroupId;
  title: string;
  instrument: string;
  credit: string;
  tag: LayerTag;
  /** What it shows, in plain words. */
  blurb: string;
  /** Unit of the underlying quantity, when the source states one. */
  units: string | null;
  /** Tile file extension. */
  ext: "png" | "jpg";
  /** Deepest zoom the service offers (zoom z is 2^(z+1) × 2^z tiles of 256 px, equirectangular). */
  maxZoom: number;
  /** Footprint [west, south, east, north], degrees. Tiles outside it do not exist. */
  bbox: [number, number, number, number];
}

export const LAYER_GROUPS: Array<{ id: LayerGroupId; label: string }> = [{"id": "light", "label": "Light & shadow"}, {"id": "terrain", "label": "Terrain & hazards"}, {"id": "thermal", "label": "Temperature"}, {"id": "chemistry", "label": "Chemistry & minerals"}, {"id": "water", "label": "Water, radar & resources"}, {"id": "gravity", "label": "Gravity"}, {"id": "geology", "label": "Geology"}, {"id": "imagery", "label": "Imagery"}];

