export const layerById = (id: string | null): DataLayer | null => (id ? (DATA_LAYERS.find((l) => l.id === id) ?? null) : null);

/** WMTS tile URL for a layer: zoom z has 2^z rows and 2^(z+1) columns, row 0 at the north edge, col 0 at −180°. */
export const layerTileUrl = (l: DataLayer, z: number, row: number, col: number): string =>
  `${TREK_TILE_ROOT}/${l.id}/1.0.0/default/default028mm/${z}/${row}/${col}.${l.ext}`;

/** Capabilities document, the layer's own machine-readable description. */
export const layerCapabilitiesUrl = (l: DataLayer): string => `${TREK_TILE_ROOT}/${l.id}/1.0.0/WMTSCapabilities.xml`;

/** True when the layer has data south of `latDeg` (so it can be draped on the polar maps). */
export const coversSouth = (l: DataLayer, latDeg = -62): boolean => l.bbox[1] <= latDeg;

/** Pixel size of the layer's deepest level at the equator, in km (for honest "resolution" text). */
export const layerKmPerPx = (l: DataLayer): number => (2 * Math.PI * 1737.4) / (256 * 2 ** (l.maxZoom + 1));
